<section class="owner-section-page owner-page operations-page"><div class="page-heading"><span class="eyebrow">مركز التشغيل الحي</span><h1>التحديثات وحالة الخدمات</h1><p>خلِّ المستخدمين يعرفون الجديد، وغيّر حالة أي خدمة بشفافية من مكان واحد.</p></div><?php require __DIR__.'/owner_nav.php'; ?><div class="operations-grid"><section class="dashboard-card operation-panel"><div class="section-card-heading"><div><span class="card-label">سجل التحديثات</span><h2>انشر تحديثًا جديدًا</h2></div><span class="status-pill status-operational">يظهر فورًا</span></div><form method="post" action="/owner/update/save" class="form-stack"><?= csrf_field() ?><label class="field"><span>عنوان التحديث</span><input name="title" maxlength="120" required placeholder="تحسينات جديدة في ملفات الإنجاز"></label><div class="owner-inline-form"><label class="field"><span>الإصدار</span><input name="version" maxlength="40" placeholder="v2.1"></label><label class="field"><span>النوع</span><select name="kind"><option value="release">إصدار جديد</option><option value="notice">إشعار مهم</option><option value="maintenance">صيانة</option></select></label></div><label class="field"><span>وصف مختصر</span><textarea name="message" rows="4" maxlength="1200" required placeholder="ما الذي تغير؟ وما الفائدة للمستخدم؟"></textarea></label><label class="toggle-field"><input type="checkbox" name="is_published" value="1" checked><span>نشر التحديث للمستخدمين</span></label><button class="button button-gold" type="submit">نشر التحديث</button></form></section><section class="dashboard-card operation-panel"><div class="section-card-heading"><div><span class="card-label">حالة الخدمات</span><h2>تحكم بالحالة</h2></div><span class="status-pill status-operational">قابلة للتعديل</span></div><form method="post" action="/owner/service/save" class="form-stack"><?= csrf_field() ?><label class="field"><span>الخدمة</span><select name="service_key" required><?php foreach(($services??[]) as $service): ?><option value="<?= e($service['service_key']) ?>"><?= e($service['label']) ?></option><?php endforeach; ?></select></label><label class="field"><span>اسم العرض</span><input name="label" maxlength="100" required value="منصة أثر"></label><label class="field"><span>الحالة</span><select name="status"><option value="operational">تعمل طبيعيًا</option><option value="maintenance">تحت الصيانة</option><option value="outage">متوقفة مؤقتًا</option></select></label><label class="field"><span>ملاحظة للمستخدم</span><input name="note" maxlength="300" placeholder="تحديث اختياري يظهر في صفحة الحالة"></label><button class="button button-navy" type="submit">حفظ الحالة</button></form></section></div><section class="dashboard-card operations-history"><div class="section-card-heading"><div><span class="card-label">المعلن حاليًا</span><h2>آخر التحديثات</h2></div></div><div class="updates-list"><?php foreach(($updates??[]) as $update): ?><article class="update-row"><div><span class="update-kind"><?= e($update['version']?:'تحديث') ?></span><h3><?= e($update['title']) ?></h3><p><?= nl2br(e($update['message'])) ?></p></div><time><?= e(saudi_datetime($update['created_at'])) ?></time></article><?php endforeach; if(empty($updates)): ?><p class="helper-note">لم تُنشر تحديثات بعد.</p><?php endif; ?></div></section><section class="dashboard-card operations-history"><div class="section-card-heading"><div><span class="card-label">لوحة الحالة</span><h2>الخدمات الحالية</h2></div></div><div class="service-status-grid"><?php foreach(($services??[]) as $service): ?><article class="service-status-card"><span class="status-dot status-<?= e($service['status']) ?>"></span><div><strong><?= e($service['label']) ?></strong><small><?= e($service['note']) ?></small></div><b><?= $service['status']==='operational'?'تعمل':($service['status']==='maintenance'?'صيانة':'متوقفة') ?></b></article><?php endforeach; ?></div></section></section>